(() => {
  const T = window.__three
  const visible = (o) => { let p = o; while (p) { if (!p.visible) return false; p = p.parent } return true }
  let twins = 0, twinsVisible = 0, fadedBodies = 0
  const depth = {}
  const ops = []
  T.scene.traverse((o) => {
    if (!o.isMesh) return
    if (o.userData && o.userData.wallRevealPrepass === true) {
      twins++
      if (visible(o)) twinsVisible++
      return
    }
    const ms = Array.isArray(o.material) ? o.material : [o.material]
    const m = ms[0]
    if (!m || !visible(o)) return
    if (!(m.transparent === true && m.opacity > 0.02 && m.opacity < 0.985)) return
    if (!o.geometry || o.geometry.type !== 'ExtrudeGeometry') return
    fadedBodies++
    ops.push(+m.opacity.toFixed(3))
    const k = 'depthFunc' + m.depthFunc + '/depthWrite' + m.depthWrite + '/order' + o.renderOrder
    depth[k] = (depth[k] || 0) + 1
  })
  console.log('[probe] prepass-census 02-orbit-living-corner ' + JSON.stringify({ twins, twinsVisible, fadedBodies, depth, ops }))
})()

(() => {
  const T = window.__three
  const st = window.__store.getState()
  const cam = T.camera
  const el = T.gl.domElement
  const W = el.clientWidth, H = el.clientHeight
  const rc = T.raycaster
  const STEP = 2
  const visible = (o) => { let p = o; while (p) { if (!p.visible) return false; p = p.parent } return true }
  // A FADED WALL fragment: a transparent, mid-opacity mesh built from the wall body's
  // ExtrudeGeometry. During a reveal fade every wall OVERLAY (face plane, trim, section cap) is
  // hidden (WALL-FADE-OVERLAY-CULL), so the extruded body is the only wall mesh drawn — which
  // makes the geometry type an exact discriminator against the door leaves / window glass that
  // fade with their host wall. The WALL-REVEAL-DEPTH-PREPASS twins are `raycast`-disabled AND
  // `colorWrite: false`, so they are never counted either way.
  const isFadedWall = (o) => {
    if (!o.isMesh || !visible(o)) return false
    if (!o.geometry || o.geometry.type !== 'ExtrudeGeometry') return false
    const ms = Array.isArray(o.material) ? o.material : [o.material]
    const m = ms[0]
    return !!m && m.transparent === true && m.opacity > 0.02 && m.opacity < 0.985
  }
  // THE BAND, defined as the defect itself rather than as "two walls stack here".
  //
  // WALL-REVEAL-SINGLE-LAYER already fixes an ordinary stack: the two walls' per-object
  // `renderOrder` (from each MIDPOINT's view-space depth) happens to agree with which SURFACE is
  // nearer, so the nearest fragment draws first, writes depth, and the one behind depth-fails.
  // The residual defect is the pixels where that agreement FAILS — the nearest faded surface
  // belongs to the wall with the HIGHER (later-drawn) order, so it blends SECOND and its alpha
  // accumulates on top. That is exactly a corner where a thin wall's buried end sits inside a
  // thick wall's body, and it is what the depth pre-pass removes.
  //
  // `renderOrder` is identical in both arms (the pre-pass does not touch it), so both arms
  // classify the SAME pixels — which is what makes the luminance comparison an A/B.
  const inverted = [], ok = []
  let rays = 0, anyFaded = 0, stacked = 0
  for (let y = 1; y < H; y += STEP) {
    for (let x = 1; x < W; x += STEP) {
      rays++
      rc.setFromCamera({ x: (x / W) * 2 - 1, y: -(y / H) * 2 + 1 }, cam)
      const hits = rc.intersectObjects(T.scene.children, true)
      const orders = []
      const seen = new Set()
      for (const h of hits) {
        const o = h.object
        if (!visible(o)) continue
        const ms = Array.isArray(o.material) ? o.material : [o.material]
        const m = ms[0]
        if (!m) continue
        if (m.colorWrite === false) continue
        if (isFadedWall(o)) { if (!seen.has(o.id)) { seen.add(o.id); orders.push(o.renderOrder) } ; continue }
        if (m.transparent === true && m.opacity < 0.985) continue // other translucent: keep going
        break // first OPAQUE surface ends the walk
      }
      if (orders.length === 0) continue
      anyFaded++
      if (orders.length > 1) stacked++
      let min = orders[0]
      for (const o of orders) if (o < min) min = o
      if (orders[0] > min) inverted.push([x, y])
      else ok.push([x, y])
    }
  }
  window.__pp = window.__pp || []
  window.__pp.push({
    head: { pose: "02-orbit-living-corner", flag: st.featureFlags.wallRevealDepthPrepass,
      single_layer_flag: st.featureFlags.wallRevealSingleLayer,
      w: W, h: H, step: STEP, rays, fadedPx: anyFaded, stackedPx: stacked,
      bandPx: inverted.length, okPx: ok.length },
    band: inverted, ok,
  })
})()

